WITH RECURSIVE daily_net AS (SELECT customer_id,date(txn_date) d,SUM(CASE WHEN txn_type='deposit' THEN txn_amount ELSE -txn_amount END) net FROM customer_transactions GROUP BY customer_id,d), bounds AS (SELECT customer_id,MIN(d) first_d,MAX(d) last_d FROM daily_net GROUP BY customer_id), spine(customer_id,d,first_d) AS (SELECT customer_id,first_d,first_d FROM bounds UNION ALL SELECT customer_id,date(d,'+1 day'),first_d FROM spine WHERE d<(SELECT MAX(d) FROM daily_net)), filled AS (SELECT s.customer_id,s.d,s.first_d,COALESCE(n.net,0) net FROM spine s LEFT JOIN daily_net n ON s.customer_id=n.customer_id AND s.d=n.d), balance AS (SELECT *,SUM(net) OVER(PARTITION BY customer_id ORDER BY d ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) closing FROM filled), rolling AS (SELECT *,COUNT(*) OVER(PARTITION BY customer_id ORDER BY d ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) days,AVG(closing) OVER(PARTITION BY customer_id ORDER BY d ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) avg30,SUM(closing) OVER(PARTITION BY customer_id ORDER BY d ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) sum30 FROM balance), monthly_max AS (SELECT customer_id,date(d,'start of month') m,MAX(MAX(avg30,0)) max_avg30 FROM rolling WHERE days=30 AND date(d,'start of month')>date(first_d,'start of month') GROUP BY customer_id,m) 